  1	package com.pousadamarealta;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousadamarealta.controller.MessageController;
  7	import com.pousadamarealta.controller.ReportController;
  8	import com.pousadamarealta.controller.ReservationController;
  9	import com.pousadamarealta.controller.RoomController;
 10	import com.pousadamarealta.database.DatabaseManager;
 11	import com.pousadamarealta.repository.MessageRepository;
 12	import com.pousadamarealta.repository.ReservationRepository;
 13	import com.pousadamarealta.repository.RoomRepository;
 14	import com.pousadamarealta.service.MessageService;
 15	import com.pousadamarealta.service.ReportService;
 16	import com.pousadamarealta.service.ReservationService;
 17	import io.javalin.Javalin;
 18	import io.javalin.json.JavalinJackson;
 19	
 20	public class Main {
 21	    public static void main(String[] args) {
 22	        String dbUrl = System.getenv("DB_URL");
 23	        String dbUser = System.getenv("DB_USER");
 24	        String dbPassword = System.getenv("DB_PASSWORD");
 25	        String portStr = System.getenv("PORT");
 26	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 27	
 28	        int port = portStr != null ? Integer.parseInt(portStr) : 7070;
 29	
 30	        DatabaseManager.initialize(dbUrl, dbUser, dbPassword);
 31	
 32	        RoomRepository roomRepository = new RoomRepository();
 33	        ReservationRepository reservationRepository = new ReservationRepository();
 34	        MessageRepository messageRepository = new MessageRepository();
 35	
 36	        MessageService messageService = new MessageService(messageRepository, testMode);
 37	        ReservationService reservationService = new ReservationService(
 38	                reservationRepository, roomRepository, messageService);
 39	        ReportService reportService = new ReportService(reservationService, roomRepository);
 40	
 41	        RoomController roomController = new RoomController(roomRepository);
 42	        ReservationController reservationController = new ReservationController(
 43	                reservationService, roomRepository);
 44	        MessageController messageController = new MessageController(messageService);
 45	        ReportController reportController = new ReportController(reportService);
 46	
 47	        ObjectMapper objectMapper = new ObjectMapper();
 48	        objectMapper.registerModule(new JavaTimeModule());
 49	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 50	
 51	        Javalin app = Javalin.create(config -> {
 52	            config.jsonMapper(new JavalinJackson(objectMapper, false));
 53	        });
 54	
 55	        app.get("/rooms", roomController::getAll);
 56	        app.post("/reservations", reservationController::create);
 57	        app.get("/reservations/{id}", reservationController::getById);
 58	        app.post("/reservations/{id}/confirmation", reservationController::confirm);
 59	        app.post("/reservations/{id}/cancellation", reservationController::cancel);
 60	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 61	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 62	        app.get("/reservations/{id}/document", reservationController::getDocument);
 63	        app.get("/messages", messageController::getAll);
 64	        app.get("/reports/occupancy", reportController::getOccupancy);
 65	        app.get("/reports/revenue", reportController::getRevenue);
 66	
 67	        app.start(port);
 68	
 69	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 70	            app.stop();
 71	            DatabaseManager.close();
 72	        }));
 73	    }
 74	}
 75	package com.pousadamarealta.controller;
 76	
 77	import com.pousadamarealta.model.Message;
 78	import com.pousadamarealta.service.MessageService;
 79	import io.javalin.http.Context;
 80	
 81	import java.util.HashMap;
 82	import java.util.List;
 83	import java.util.Map;
 84	
 85	public class MessageController {
 86	    private final MessageService messageService;
 87	
 88	    public MessageController(MessageService messageService) {
 89	        this.messageService = messageService;
 90	    }
 91	
 92	    public void getAll(Context ctx) {
 93	        List<Message> messages = messageService.findAll();
 94	        List<Map<String, Object>> response = messages.stream()
 95	                .map(this::toMap)
 96	                .toList();
 97	        ctx.json(response);
 98	    }
 99	
100	    private Map<String, Object> toMap(Message message) {
101	        Map<String, Object> map = new HashMap<>();
102	        map.put("id", message.getId());
103	        map.put("channel", message.getChannel().name());
104	        map.put("to", message.getTo());
105	        map.put("subject", message.getSubject());
106	        map.put("body", message.getBody());
107	        map.put("status", message.getStatus().name());
108	        return map;
109	    }
110	}
111	package com.pousadamarealta.controller;
112	
113	import com.pousadamarealta.service.ReportService;
114	import io.javalin.http.Context;
115	
116	import java.time.LocalDate;
117	import java.time.format.DateTimeParseException;
118	import java.util.Map;
119	
120	public class ReportController {
121	    private final ReportService reportService;
122	
123	    public ReportController(ReportService reportService) {
124	        this.reportService = reportService;
125	    }
126	
127	    public void getOccupancy(Context ctx) {
128	        try {
129	            String dateStr = ctx.queryParam("date");
130	            if (dateStr == null) {
131	                ctx.status(400).json(Map.of(
132	                    "error", "INVALID_REQUEST",
133	                    "message", "Missing date parameter"
134	                ));
135	                return;
136	            }
137	
138	            LocalDate date = LocalDate.parse(dateStr);
139	            String csv = reportService.generateOccupancyReport(date);
140	
141	            ctx.contentType("text/csv; charset=utf-8");
142	            ctx.result(csv);
143	        } catch (DateTimeParseException e) {
144	            ctx.status(400).json(Map.of(
145	                "error", "INVALID_REQUEST",
146	                "message", "Invalid date format"
147	            ));
148	        }
149	    }
150	
151	    public void getRevenue(Context ctx) {
152	        try {
153	            String monthStr = ctx.queryParam("month");
154	            if (monthStr == null) {
155	                ctx.status(400).json(Map.of(
156	                    "error", "INVALID_REQUEST",
157	                    "message", "Missing month parameter"
158	                ));
159	                return;
160	            }
161	
162	            String[] parts = monthStr.split("-");
163	            if (parts.length != 2) {
164	                ctx.status(400).json(Map.of(
165	                    "error", "INVALID_REQUEST",
166	                    "message", "Invalid month format"
167	                ));
168	                return;
169	            }
170	
171	            int year = Integer.parseInt(parts[0]);
172	            int month = Integer.parseInt(parts[1]);
173	
174	            String csv = reportService.generateRevenueReport(year, month);
175	
176	            ctx.contentType("text/csv; charset=utf-8");
177	            ctx.result(csv);
178	        } catch (NumberFormatException e) {
179	            ctx.status(400).json(Map.of(
180	                "error", "INVALID_REQUEST",
181	                "message", "Invalid month format"
182	            ));
183	        }
184	    }
185	}
186	package com.pousadamarealta.controller;
187	
188	import com.pousadamarealta.model.RatePlan;
189	import com.pousadamarealta.model.Reservation;
190	import com.pousadamarealta.model.ReservationDocument;
191	import com.pousadamarealta.model.Room;
192	import com.pousadamarealta.repository.RoomRepository;
193	import com.pousadamarealta.service.ReservationService;
194	import io.javalin.http.Context;
195	
196	import java.math.BigDecimal;
197	import java.time.LocalDate;
198	import java.time.format.DateTimeParseException;
199	import java.util.HashMap;
200	import java.util.Map;
201	
202	public class ReservationController {
203	    private final ReservationService reservationService;
204	    private final RoomRepository roomRepository;
205	
206	    public ReservationController(ReservationService reservationService, RoomRepository roomRepository) {
207	        this.reservationService = reservationService;
208	        this.roomRepository = roomRepository;
209	    }
210	
211	    public void create(Context ctx) {
212	        try {
213	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
214	
215	            Reservation reservation = new Reservation();
216	            reservation.setRoomNumber((String) body.get("roomNumber"));
217	            reservation.setGuestName((String) body.get("guestName"));
218	            reservation.setGuestEmail((String) body.get("guestEmail"));
219	            reservation.setGuestCpf((String) body.get("guestCpf"));
220	
221	            try {
222	                reservation.setCheckIn(LocalDate.parse((String) body.get("checkIn")));
223	                reservation.setCheckOut(LocalDate.parse((String) body.get("checkOut")));
224	            } catch (DateTimeParseException e) {
225	                ctx.status(400).json(Map.of(
226	                    "error", "INVALID_REQUEST",
227	                    "message", "Invalid date format"
228	                ));
229	                return;
230	            }
231	
232	            if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
233	                reservation.getCheckOut().isEqual(reservation.getCheckIn())) {
234	                ctx.status(400).json(Map.of(
235	                    "error", "INVALID_REQUEST",
236	                    "message", "Check-out must be after check-in"
237	                ));
238	                return;
239	            }
240	
241	            int guests = ((Number) body.get("guests")).intValue();
242	            if (guests < 1) {
243	                ctx.status(400).json(Map.of(
244	                    "error", "INVALID_REQUEST",
245	                    "message", "At least one guest is required"
246	                ));
247	                return;
248	            }
249	            reservation.setGuests(guests);
250	
251	            try {
252	                reservation.setRatePlan(RatePlan.valueOf((String) body.get("ratePlan")));
253	            } catch (IllegalArgumentException e) {
254	                ctx.status(400).json(Map.of(
255	                    "error", "INVALID_REQUEST",
256	                    "message", "Invalid rate plan"
257	                ));
258	                return;
259	            }
260	
261	            Reservation created = reservationService.create(reservation);
262	            ctx.status(201).json(toMap(created));
263	
264	        } catch (ReservationService.RoomNotFoundException e) {
265	            ctx.status(404).json(Map.of(
266	                "error", "ROOM_NOT_FOUND",
267	                "message", "Room not found"
268	            ));
269	        } catch (ReservationService.CapacityExceededException e) {
270	            ctx.status(422).json(Map.of(
271	                "error", "CAPACITY_EXCEEDED",
272	                "message", "Number of guests exceeds room capacity"
273	            ));
274	        } catch (ReservationService.RoomUnavailableException e) {
275	            ctx.status(409).json(Map.of(
276	                "error", "ROOM_UNAVAILABLE",
277	                "message", "Room is not available for the selected dates"
278	            ));
279	        } catch (Exception e) {
280	            ctx.status(400).json(Map.of(
281	                "error", "INVALID_REQUEST",
282	                "message", e.getMessage()
283	            ));
284	        }
285	    }
286	
287	    public void getById(Context ctx) {
288	        try {
289	            Long id = Long.parseLong(ctx.pathParam("id"));
290	            Reservation reservation = reservationService.findById(id);
291	            ctx.json(toMap(reservation));
292	        } catch (ReservationService.ReservationNotFoundException e) {
293	            ctx.status(404).json(Map.of(
294	                "error", "RESERVATION_NOT_FOUND",
295	                "message", "Reservation not found"
296	            ));
297	        }
298	    }
299	
300	    public void confirm(Context ctx) {
301	        try {
302	            Long id = Long.parseLong(ctx.pathParam("id"));
303	            Reservation reservation = reservationService.confirm(id);
304	            ctx.json(toMap(reservation));
305	        } catch (ReservationService.ReservationNotFoundException e) {
306	            ctx.status(404).json(Map.of(
307	                "error", "RESERVATION_NOT_FOUND",
308	                "message", "Reservation not found"
309	            ));
310	        } catch (ReservationService.OperationNotAllowedException e) {
311	            ctx.status(409).json(Map.of(
312	                "error", "OPERATION_NOT_ALLOWED",
313	                "message", "Operation not allowed for current reservation status"
314	            ));
315	        }
316	    }
317	
318	    public void cancel(Context ctx) {
319	        try {
320	            Long id = Long.parseLong(ctx.pathParam("id"));
321	            Reservation reservation = reservationService.cancel(id);
322	            ctx.json(toMap(reservation));
323	        } catch (ReservationService.ReservationNotFoundException e) {
324	            ctx.status(404).json(Map.of(
325	                "error", "RESERVATION_NOT_FOUND",
326	                "message", "Reservation not found"
327	            ));
328	        } catch (ReservationService.OperationNotAllowedException e) {
329	            ctx.status(409).json(Map.of(
330	                "error", "OPERATION_NOT_ALLOWED",
331	                "message", "Operation not allowed for current reservation status"
332	            ));
333	        }
334	    }
335	
336	    public void checkIn(Context ctx) {
337	        try {
338	            Long id = Long.parseLong(ctx.pathParam("id"));
339	            Reservation reservation = reservationService.checkIn(id);
340	            ctx.json(toMap(reservation));
341	        } catch (ReservationService.ReservationNotFoundException e) {
342	            ctx.status(404).json(Map.of(
343	                "error", "RESERVATION_NOT_FOUND",
344	                "message", "Reservation not found"
345	            ));
346	        } catch (ReservationService.OperationNotAllowedException e) {
347	            ctx.status(409).json(Map.of(
348	                "error", "OPERATION_NOT_ALLOWED",
349	                "message", "Operation not allowed for current reservation status"
350	            ));
351	        }
352	    }
353	
354	    public void checkOut(Context ctx) {
355	        try {
356	            Long id = Long.parseLong(ctx.pathParam("id"));
357	            Reservation reservation = reservationService.checkOut(id);
358	            ReservationDocument document = reservationService.getDocument(id);
359	            ctx.json(toDocumentMap(document));
360	        } catch (ReservationService.ReservationNotFoundException e) {
361	            ctx.status(404).json(Map.of(
362	                "error", "RESERVATION_NOT_FOUND",
363	                "message", "Reservation not found"
364	            ));
365	        } catch (ReservationService.OperationNotAllowedException e) {
366	            ctx.status(409).json(Map.of(
367	                "error", "OPERATION_NOT_ALLOWED",
368	                "message", "Operation not allowed for current reservation status"
369	            ));
370	        }
371	    }
372	
373	    public void getDocument(Context ctx) {
374	        try {
375	            Long id = Long.parseLong(ctx.pathParam("id"));
376	            ReservationDocument document = reservationService.getDocument(id);
377	            ctx.json(toDocumentMap(document));
378	        } catch (ReservationService.ReservationNotFoundException e) {
379	            ctx.status(404).json(Map.of(
380	                "error", "RESERVATION_NOT_FOUND",
381	                "message", "Reservation not found"
382	            ));
383	        }
384	    }
385	
386	    private Map<String, Object> toMap(Reservation reservation) {
387	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
388	        BigDecimal subtotal = reservation.calculateSubtotal(room.getNightlyRate());
389	        BigDecimal discount = reservation.calculateDiscount(subtotal);
390	        BigDecimal total = subtotal.subtract(discount);
391	
392	        Map<String, Object> map = new HashMap<>();
393	        map.put("id", reservation.getId());
394	        map.put("roomNumber", reservation.getRoomNumber());
395	        map.put("guestName", reservation.getGuestName());
396	        map.put("guestEmail", reservation.getGuestEmail());
397	        map.put("guestCpf", reservation.getGuestCpf());
398	        map.put("checkIn", reservation.getCheckIn().toString());
399	        map.put("checkOut", reservation.getCheckOut().toString());
400	        map.put("guests", reservation.getGuests());
401	        map.put("ratePlan", reservation.getRatePlan().name());
402	        map.put("nights", reservation.getNights());
403	        map.put("subtotal", subtotal);
404	        map.put("discount", discount);
405	        map.put("total", total);
406	        map.put("status", reservation.getStatus().name());
407	        map.put("amountPaid", reservation.getAmountPaid());
408	        map.put("refund", reservation.getRefund());
409	        return map;
410	    }
411	
412	    private Map<String, Object> toDocumentMap(ReservationDocument doc) {
413	        Map<String, Object> map = new HashMap<>();
414	        map.put("title", doc.getTitle());
415	        map.put("reservationId", doc.getReservationId());
416	        map.put("guestName", doc.getGuestName());
417	        map.put("guestCpf", doc.getGuestCpf());
418	        map.put("roomNumber", doc.getRoomNumber());
419	        map.put("roomType", doc.getRoomType());
420	        map.put("checkIn", doc.getCheckIn().toString());
421	        map.put("checkOut", doc.getCheckOut().toString());
422	        map.put("nights", doc.getNights());
423	        map.put("subtotal", doc.getSubtotal());
424	        map.put("discount", doc.getDiscount());
425	        map.put("total", doc.getTotal());
426	        return map;
427	    }
428	}
