163	            if (parts.length != 2) {
164	                ctx.status(400).json(Map.of(
165	                    "error", "INVALID_REQUEST",
166	                    "message", "Invalid month format"
167	                ));
168	                return;
169	            }
170	
171	            int year = Integer.parseInt(parts[0]);
172	            int month = Integer.parseInt(parts[1]);
173	
174	            String csv = reportService.generateRevenueReport(year, month);
175	
176	            ctx.contentType("text/csv; charset=utf-8");
177	            ctx.result(csv);
