 74	        StringBuilder csv = new StringBuilder();
 75	
 76	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 77	
 78	        BigDecimal total = BigDecimal.ZERO;
 79	
 80	        for (Reservation r : reservations) {
 81	            BigDecimal revenue = r.getAmountPaid();
 82	            if (r.getRefund() != null) {
 83	                revenue = revenue.subtract(r.getRefund());
 84	            }
 85	
 86	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
 87	                csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
 88	                        r.getId(),
 89	                        r.getRoomNumber(),
 90	                        r.getCheckIn(),
 91	                        r.getCheckOut(),
 92	                        r.getStatus().name(),
 93	                        formatCsvAmount(revenue)));
 94	
 95	                total = total.add(revenue);
 96	            }
 97	        }
 98	
 99	        csv.append(String.format("total,%s\n", formatCsvAmount(total)));
100	
101	        return csv.toString();
102	    }
