108	package com.pousadamarealta.service;
109	
110	import com.pousadamarealta.model.*;
111	import com.pousadamarealta.repository.ReservationRepository;
112	import com.pousadamarealta.repository.RoomRepository;
113	
114	import java.math.BigDecimal;
115	import java.time.LocalDate;
116	import java.util.List;
117	
118	public class ReservationService {
119	    private final ReservationRepository reservationRepository;
120	    private final RoomRepository roomRepository;
121	    private final MessageService messageService;
122	
123	    public ReservationService(ReservationRepository reservationRepository,
124	                            RoomRepository roomRepository,
125	                            MessageService messageService) {
126	        this.reservationRepository = reservationRepository;
127	        this.roomRepository = roomRepository;
128	        this.messageService = messageService;
129	    }
130	
131	    public Reservation create(Reservation reservation) {
132	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
133	                .orElseThrow(() -> new RoomNotFoundException());
134	
135	        if (reservation.getGuests() > room.getCapacity()) {
136	            throw new CapacityExceededException();
137	        }
138	
139	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(
140	                reservation.getRoomNumber(),
141	                reservation.getCheckIn(),
142	                reservation.getCheckOut()
143	        );
144	
145	        if (!conflicts.isEmpty()) {
146	            throw new RoomUnavailableException();
147	        }
148	
149	        return reservationRepository.save(reservation);
150	    }
151	
152	    public Reservation findById(Long id) {
153	        return reservationRepository.findById(id)
154	                .orElseThrow(() -> new ReservationNotFoundException());
155	    }
156	
157	    public Reservation confirm(Long id) {
158	        Reservation reservation = findById(id);
159	
160	        if (reservation.getStatus() != ReservationStatus.PENDING) {
161	            throw new OperationNotAllowedException();
162	        }
163	
164	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
165	        BigDecimal subtotal = reservation.calculateSubtotal(room.getNightlyRate());
166	        BigDecimal discount = reservation.calculateDiscount(subtotal);
167	        BigDecimal total = subtotal.subtract(discount);
168	
169	        reservation.setStatus(ReservationStatus.CONFIRMED);
170	        reservation.setAmountPaid(total);
171	
172	        Reservation saved = reservationRepository.save(reservation);
173	
174	        sendConfirmationEmail(saved, room, subtotal, discount, total);
175	
176	        return saved;
177	    }
178	
179	    public Reservation cancel(Long id) {
180	        Reservation reservation = findById(id);
181	
182	        if (reservation.getStatus() != ReservationStatus.PENDING &&
183	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
184	            throw new OperationNotAllowedException();
185	        }
186	
187	        BigDecimal refund = BigDecimal.ZERO;
188	
189	        if (reservation.getStatus() == ReservationStatus.CONFIRMED &&
190	            reservation.getRatePlan() == RatePlan.STANDARD) {
191	            refund = reservation.getAmountPaid();
192	        }
193	
194	        reservation.setStatus(ReservationStatus.CANCELLED);
195	        reservation.setRefund(refund);
196	
197	        return reservationRepository.save(reservation);
198	    }
199	
200	    public Reservation checkIn(Long id) {
201	        Reservation reservation = findById(id);
202	
203	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
204	            throw new OperationNotAllowedException();
205	        }
206	
207	        reservation.setStatus(ReservationStatus.CHECKED_IN);
208	        return reservationRepository.save(reservation);
209	    }
210	
211	    public Reservation checkOut(Long id) {
212	        Reservation reservation = findById(id);
213	
214	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
215	            throw new OperationNotAllowedException();
216	        }
217	
218	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
219	        return reservationRepository.save(reservation);
220	    }
221	
222	    public ReservationDocument getDocument(Long id) {
223	        Reservation reservation = findById(id);
224	
225	        if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
226	            reservation.getStatus() != ReservationStatus.CHECKED_IN &&
227	            reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
228	            return null;
229	        }
230	
231	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).get();
232	        BigDecimal subtotal = reservation.calculateSubtotal(room.getNightlyRate());
233	        BigDecimal discount = reservation.calculateDiscount(subtotal);
234	        BigDecimal total = subtotal.subtract(discount);
235	
236	        return createDocument(reservation, room, subtotal, discount, total);
237	    }
238	
239	    private void sendConfirmationEmail(Reservation reservation, Room room,
240	                                     BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
241	        ReservationDocument doc = createDocument(reservation, room, subtotal, discount, total);
242	        String receipt = formatReceipt(doc);
243	
244	        String body = String.format("""
245	            Olá, %s!
246	
247	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
248	
249	            %s
250	
251	            A entrada é a partir das 14h, e a saída, até as 12h.
252	            Até breve!""", reservation.getGuestName(), receipt);
253	
254	        Message message = new Message(
255	            MessageChannel.EMAIL,
256	            reservation.getGuestEmail(),
257	            "Reserva confirmada - Pousada Maré Alta",
258	            body
259	        );
260	
261	        messageService.send(message);
262	    }
263	
264	    private ReservationDocument createDocument(Reservation reservation, Room room,
265	                                             BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
266	        ReservationDocument doc = new ReservationDocument();
267	        doc.setTitle("Comprovante de reserva");
268	        doc.setReservationId(reservation.getId());
269	        doc.setGuestName(reservation.getGuestName());
270	        doc.setGuestCpf(reservation.getGuestCpf());
271	        doc.setRoomNumber(reservation.getRoomNumber());
272	        doc.setRoomType(room.getType().name());
273	        doc.setCheckIn(reservation.getCheckIn());
274	        doc.setCheckOut(reservation.getCheckOut());
275	        doc.setNights(reservation.getNights());
276	        doc.setSubtotal(subtotal);
277	        doc.setDiscount(discount.compareTo(BigDecimal.ZERO) > 0 ? discount : null);
278	        doc.setTotal(total);
279	        return doc;
280	    }
281	
282	    private String formatReceipt(ReservationDocument doc) {
283	        StringBuilder sb = new StringBuilder();
284	        sb.append(String.format("Comprovante de reserva nº %d\n", doc.getReservationId()));
285	        sb.append(String.format("Hóspede: %s (CPF %s)\n", doc.getGuestName(), doc.getGuestCpf()));
286	        sb.append(String.format("Quarto: %s (%s)\n", doc.getRoomNumber(), doc.getRoomType()));
287	        sb.append(String.format("Entrada: %s | Saída: %s | %d diária%s\n",
288	                formatDate(doc.getCheckIn()),
289	                formatDate(doc.getCheckOut()),
290	                doc.getNights(),
291	                doc.getNights() == 1 ? "" : "s"));
292	        sb.append(String.format("Diárias: %s\n", formatMoney(doc.getSubtotal())));
293	
294	        if (doc.getDiscount() != null) {
295	            sb.append(String.format("Desconto: %s\n", formatMoney(doc.getDiscount())));
296	        }
297	
298	        sb.append(String.format("Total: %s", formatMoney(doc.getTotal())));
299	
300	        return sb.toString();
301	    }
302	
303	    private String formatDate(LocalDate date) {
304	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
305	    }
306	
307	    private String formatMoney(BigDecimal amount) {
308	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
309	    }
310	
311	    public List<Reservation> findByDate(LocalDate date) {
312	        return reservationRepository.findByDate(date);
313	    }
314	
315	    public List<Reservation> findByMonth(int year, int month) {
316	        return reservationRepository.findByMonth(year, month);
317	    }
