320	    public static class ReservationNotFoundException extends RuntimeException {}
321	    public static class RoomUnavailableException extends RuntimeException {}
322	    public static class CapacityExceededException extends RuntimeException {}
323	    public static class OperationNotAllowedException extends RuntimeException {}
324	}
