179	    public Reservation cancel(Long id) {
180	        Reservation reservation = findById(id);
181	
182	        if (reservation.getStatus() != ReservationStatus.PENDING &&
183	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
184	            throw new OperationNotAllowedException();
185	        }
186	
187	        BigDecimal refund = BigDecimal.ZERO;
188	
189	        if (reservation.getStatus() == ReservationStatus.CONFIRMED &&
190	            reservation.getRatePlan() == RatePlan.STANDARD) {
191	            refund = reservation.getAmountPaid();
192	        }
193	
194	        reservation.setStatus(ReservationStatus.CANCELLED);
195	        reservation.setRefund(refund);
196	
197	        return reservationRepository.save(reservation);
