 26	import com.pousadamarealta.model.MessageStatus;
 27	
 28	public class EmailValidationRule implements MessageRule {
 29	
 30	    @Override
 31	    public void apply(MessageRuleContext context) {
 32	        String email = context.getCurrentMessage().getTo();
 33	
 34	        if (!isValidEmail(email)) {
 35	            context.block();
 36	            context.getCurrentMessage().setStatus(MessageStatus.BLOCKED);
 37	        }
 38	    }
 39	
 40	    private boolean isValidEmail(String email) {
 41	        if (email == null || email.isEmpty()) {
 42	            return false;
 43	        }
 44	
 45	        long atCount = email.chars().filter(c -> c == '@').count();
 46	        if (atCount != 1) {
 47	            return false;
 48	        }
 49	
 50	        int atIndex = email.indexOf('@');
 51	        if (atIndex == 0 || atIndex == email.length() - 1) {
 52	            return false;
 53	        }
 54	
 55	        String beforeAt = email.substring(0, atIndex);
 56	        String afterAt = email.substring(atIndex + 1);
 57	
 58	        if (beforeAt.isEmpty()) {
 59	            return false;
 60	        }
 61	
 62	        if (!afterAt.contains(".")) {
 63	            return false;
 64	        }
 65	
 66	        return true;
 67	    }
 68	}
