153	public class MessageRulePipeline {
154	    private final List<MessageRule> rules;
155	
156	    public MessageRulePipeline(List<MessageRule> rules) {
157	        this.rules = new ArrayList<>(rules);
158	    }
159	
160	    public List<Message> process(Message message) {
161	        MessageRuleContext context = new MessageRuleContext(message);
162	
163	        for (MessageRule rule : rules) {
164	            rule.apply(context);
165	        }
166	
167	        List<Message> result = new ArrayList<>();
168	        result.add(context.getCurrentMessage());
169	        result.addAll(context.getAdditionalMessages());
170	
171	        return result;
172	    }
173	}
