432	            List<Reservation> reservations = new ArrayList<>();
433	
434	            while (rs.next()) {
435	                reservations.add(mapRow(rs));
436	            }
437	
438	            return reservations;
439	        } catch (SQLException e) {
440	            throw new RuntimeException("Failed to find reservations by date", e);
441	        }
442	    }
443	
444	    public List<Reservation> findByMonth(int year, int month) {
445	        String sql = """
446	            SELECT * FROM reservations
447	            WHERE EXTRACT(YEAR FROM check_in) = ?
448	              AND EXTRACT(MONTH FROM check_in) = ?
449	            ORDER BY check_in, id
450	        """;
451	
452	        try (Connection conn = DatabaseManager.getConnection();
453	             PreparedStatement stmt = conn.prepareStatement(sql)) {
454	
455	            stmt.setInt(1, year);
456	            stmt.setInt(2, month);
457	
458	            ResultSet rs = stmt.executeQuery();
459	            List<Reservation> reservations = new ArrayList<>();
460	
461	            while (rs.next()) {
462	                reservations.add(mapRow(rs));
463	            }
464	
465	            return reservations;
466	        } catch (SQLException e) {
467	            throw new RuntimeException("Failed to find reservations by month", e);
468	        }
469	    }
470	
471	    private Reservation mapRow(ResultSet rs) throws SQLException {
472	        Reservation reservation = new Reservation();
473	        reservation.setId(rs.getLong("id"));
474	        reservation.setRoomNumber(rs.getString("room_number"));
475	        reservation.setGuestName(rs.getString("guest_name"));
476	        reservation.setGuestEmail(rs.getString("guest_email"));
477	        reservation.setGuestCpf(rs.getString("guest_cpf"));
478	        reservation.setCheckIn(rs.getDate("check_in").toLocalDate());
479	        reservation.setCheckOut(rs.getDate("check_out").toLocalDate());
