326	        this.amountPaid = amountPaid;
327	    }
328	
329	    public BigDecimal getRefund() {
330	        return refund;
331	    }
332	
333	    public void setRefund(BigDecimal refund) {
334	        this.refund = refund;
335	    }
336	
337	    public int getNights() {
338	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
339	    }
340	
341	    public BigDecimal calculateSubtotal(BigDecimal baseRate) {
342	        BigDecimal subtotal = BigDecimal.ZERO;
343	        LocalDate currentDate = checkIn;
344	
345	        while (currentDate.isBefore(checkOut)) {
346	            BigDecimal nightRate = baseRate;
347	            if (isHighSeason(currentDate)) {
348	                nightRate = nightRate.multiply(new BigDecimal("1.20"))
349	                        .setScale(2, RoundingMode.HALF_EVEN);
350	            }
351	            subtotal = subtotal.add(nightRate);
352	            currentDate = currentDate.plusDays(1);
353	        }
354	
355	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
356	    }
357	
358	    public BigDecimal calculateDiscount(BigDecimal subtotal) {
359	        if (ratePlan.getDiscountRate().compareTo(BigDecimal.ZERO) == 0) {
360	            return BigDecimal.ZERO;
361	        }
362	        return subtotal.multiply(ratePlan.getDiscountRate())
363	                .setScale(2, RoundingMode.HALF_EVEN);
364	    }
365	
366	    private boolean isHighSeason(LocalDate date) {
367	        int month = date.getMonthValue();
368	        int day = date.getDayOfMonth();
369	
370	        if (month == 7) {
371	            return true;
372	        }
373	
374	        if (month == 12 && day >= 15) {
375	            return true;
376	        }
377	
378	        if (month == 1 || month == 2) {
379	            return true;
380	        }
381	
382	        return false;
383	    }
384	}
